cavio.scss:
/*Global fonts*/
$body-secondary-font-family: stencilFontFamily("body-font-secondary"), Arial, Helvetica, sans-serif;
/*html{
    overflow-x: hidden;
}*/
$topmenu-bg-color-one: stencilColor("header-top-bg-color");
$topmenu-bg-color-two: stencilColor("header-top-bg-second-color");
$newsletterbutton-bg-color-one: stencilColor("footer-newsletter-button-background-color-one");
$newsletterbutton-bg-color-two: stencilColor("footer-newsletter-button-background-color-two");
$newsletterbutton-border-color: stencilColor("footer-newsletter-button-border-color");
$carousel-bg-color-one: stencilColor("carousel-bgColor");
$carousel-bg-color-two: stencilColor("carousel-bgColor-two");
$bg-button-primary-color-one: stencilColor("button--primary-backgroundColor");
$bg-button-primary-color-two: stencilColor("button--primary-backgroundColorTwo");
$bg-button-primary-color-one-hover: stencilColor("button--primary-backgroundColorHover");
$bg-button-primary-color-two-hover: stencilColor("button--primary-bgColorHoverTwo");
$buttons-trasitions: all 0.1s ease-in-out;
$slick-dot-trasitions: left 0.3s cubic-bezier(0.37 , 0, 0.63, 1);
$opacity-animation: fadeIn 0.1s ease-in-out forwards;
$drawer-animation: leftSlide 0.1s ease-in-out forwards;
$general-trasitions-speed: 0.1s ease-in-out;
$image-overlay-color: rgba(stencilColor("image-over-color"), 0.5);
$image-overlay-background: #000;
$image-overlay-background-secondary: linear-gradient(0deg, rgba(0, 0, 0, 1) 0%, rgba(0, 0, 0, 0.1) 100%, rgba(0, 0, 0, 1) 100%);
.parts-variant {
    .button, .cancel.button{
        padding-top: 1.15714rem;
        padding-bottom: 1.05714rem;
    }
}
body{
    padding-top: 99px;
    overflow-x: hidden;
    font-family: $body-font-family;
    @include breakpoint("medium"){
        padding-top: 0;
    }
}
.modal-background {
    opacity: 0.4;
}
h5, h6{
    text-transform: none;
}
strong, b{
    font-weight: 500;
}
.navPages-action.is-open svg, .navPages-action .collapsible-icon-wrapper.is-open svg{
    fill: stencilColor("navPages-subMenu-text-color");
    stroke: stencilColor("navPages-subMenu-text-color");
}
.slick-next, .slick-prev{
    background-color: transparent;
    border-color: transparent;
}
.slick-next:hover, .slick-next:focus, .slick-prev:hover, .slick-prev:focus{
    border-color: transparent;
    background-color: transparent;
}
.countPill{
    color:stencilColor("count-indicator");
}
.hasAdminBar{
    .page.product--listing.flyout-filters .page-sidebar{
        margin-top: 45px;
    }    
}
.form-input,.form-select{
    border-radius: 12px;
    font-family: $body-secondary-font-family;
    background-color: stencilColor("input-bg-color");
    &:focus-visible{
      border-radius: 12px;
    }    
}
.share-wishlist{
    .form-input{
        background-color: stencilColor("alert-backgroundColor");
        color: stencilColor("alert-color");        
    }
}
.button--primary:active{
    border: none;
    outline-color: #e6e6e6 !important;
}
h1, h2, h3, h4, h5, h6{
    letter-spacing: normal;
}
.form-label {
    font-family: $body-secondary-font-family;
    small{
        float: none;
        display: inline;
        vertical-align: top;
        color: stencilColor("label-validation-color");
        font-size: 12px;
    }
}
.form-field--error .form-field-error, 
.form-field--error .form-inlineMessage {
    font-family: $body-secondary-font-family;
}
h1, h2, h3, h4, h5, h6{
    font-weight: 500;
}
h1{
    line-height: 1.73;
}
.new-customer{
    .panel{
        .panel-header{
            border-radius: 12px 12px 0 0;
            background: #fafafa;
        }
        .panel-body{
            background: #fafafa;
            border-radius: 0 0 12px 12px;
        }
    }
}
.new-customer-intro {
    margin-bottom: 7px;
    font-family: $body-secondary-font-family;
}
.new-customer-fact {
    font-family: $body-secondary-font-family;
}
.forgot-password, .reset-text {
    font-family: $body-secondary-font-family;
}
.account-body{
    margin: 0;
    font-family: $body-secondary-font-family;
    h1, h2, h3, h4, h5, h6 {
        font-weight: 500;
        font-family: $body-secondary-font-family;
    }
}
.wishlists-table {
    font-family: $body-secondary-font-family;
}
a{
    transition: color $general-trasitions-speed;
}
.navUser-custom-icon,.icon{
    svg{
        transition: $buttons-trasitions;
        fill: stencilColor("header-top-user-links-color");
        stroke: stencilColor("header-top-user-links-color"); 
    }
}
@mixin global-transition{
    transition: $buttons-trasitions;
}
/* Variables start*/
/*Image Hover Effect variables Start*/
@mixin flex-box {
    display: flex;
    flex-wrap: wrap;
    flex-direction: row;
}
/*Image Hover Effect variables End*/
/*Opacity Effects Start*/
@keyframes fadeIn {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}
@keyframes leftSlide {
    from {
        left: -500px;
    }
    to {
        left: 0;
    }
}
/*Opacity Effects End*/

/* Variables end */
.or-use-label{
    text-align: center !important;
}
:focus-visible{
    transition: none;
    outline-offset: .3rem;
    border-radius: 4px;
    outline: 3px solid stencilColor("focus-outline");
}
.featured-category{
   &:focus-visible{ 
    outline: none;
   }
}
a[href],a[tabindex]:not([tabindex="-1"]){
    &:focus-visible{
        outline-offset: .3rem;
        outline: 3px solid stencilColor("focus-outline");        
        border-color: #b3b3b3;
    }
}
.product,.card-figure, .listItem-figure{
    .card-figure__link{
        &:focus-visible{
            box-shadow: none;
            border: none;
            outline-offset: 0;
            outline: 3px solid stencilColor("focus-outline");   
            border-radius: 12px;
        }        
    }
    &:focus-visible,&:focus{
        box-shadow: none;
        border: none;
        outline-offset: -3px;
        outline: 3px solid stencilColor("focus-outline") !important;
        border-radius: 12px;
    }
}
.alertBox--success svg{
    stroke: none;
    fill: stencilColor("color-success");
}
.alertBox--error svg{
    stroke: none;
    fill: stencilColor("color-error");   
}
.navList-action.is-active{
    font-weight: 500;
}
.form-input, .form-select{
    &:focus-visible{
        box-shadow: none;
          outline-offset: 0;
          outline: 3px solid stencilColor("focus-outline") !important;        
    } 
}
.productView-options{
    .form-radio{
        + .form-option{
            &::before{
                top: 18px;
                transform: rotate(-29deg);
            }
        }
    }
}
.productView-img-container img{
    max-width: 100%;
    object-fit: cover;
    @include breakpoint("medium"){
        max-width: 100%;
    }
}
.button{
    transition: none;
    &:focus-visible{
      outline-offset: -3px !important;
      outline: 3px solid stencilColor("focus-outline") !important;         
    }
}
.button,.cancel.button{
    border-radius: 12px;
    border: 1px solid stencilColor("button--default-borderColor");
    font-weight: 500;
    color: stencilColor("button--default-color");
    font-size: 1.1rem;
    padding: 1.05714rem 2.28571rem;
    background: stencilColor("button--default-BG");
    transition: $buttons-trasitions;
    &:hover{
        border-color: stencilColor("button--default-borderColorHover");
        color: stencilColor("button--default-colorHover");
        background: stencilColor("button--default-BGHover");
    }
}
.button--primary,.confirm.button{
    background: linear-gradient(90deg, $bg-button-primary-color-one 0%, $bg-button-primary-color-two 100%);
    color: stencilColor("button--primary-color");
    border-color: transparent;
    position: relative;
    border: none;
    transition: $buttons-trasitions;
    &:hover{
        border-color: transparent;
        background: linear-gradient(90deg, $bg-button-primary-color-one-hover 0%, $bg-button-primary-color-two-hover 100%);
       color: stencilColor("button--primary-color-hover");
    }
    &:focus-visible{
      outline-offset: -3px;
    }   
    &:focus{
      color: stencilColor("button--primary-color-hover");
    } 
}
.modal--alert .button-container .confirm{
    border-color: transparent;
}
.top-menu-wrapper{
    @include flex-box;
    align-items: center;
    opacity: 0;
}
.social-icons-top, .top-menu-user{
    width: 34.5%;
    display: none;
    @include breakpoint("medium"){
        width: 30%;
        display: block;
    }
    @include breakpoint("large"){
        width: 34.5%;
    }
}
.global-banner{
    width: 100%;
    max-width: 330px;
    margin-left: auto;
    margin-right: auto;    
    @include breakpoint("medium"){
        width: 40%;
        max-width: 100%;
    }
    @include breakpoint("large"){
        width: 31%;        
    }    
}
.container{
    padding: 0 20px;
    max-width: 100%;
    @include breakpoint(768px){
        padding: 0 48px;
    }
    @include breakpoint(1366px){
        padding: 0 72px;
    }
    @include breakpoint(1920px){
        padding: 0 154px;
    }
    @include breakpoint(2000px){
        padding: 0 201px;
    }
}
.page-content, .page-content--full{
    padding-left: 0;
    padding-right: 0;
}
.page-sidebar + .page-content{
    padding-left: 0;
    padding-right: 0;   
    float: right;
    transition: all $general-trasitions-speed;
}
.page{
    margin:0;
}
.body{
    margin: 0;
    padding-bottom: 50px;
}
.login{
    margin: 0 auto;
}
.login-form, .new-customer{
    padding-right: 0;
    padding-left: 0;
    @include breakpoint("medium"){
        padding-left: 0.75rem;
        padding-right: 0.75rem;
    }

}
.login-row{
    @include breakpoint("medium"){
        margin-left: -0.75rem;
        margin-right: -0.75rem;
    }
}
.panel-body{
    background-color: #f3f3f3;
}
.panel--address .panel-body{
    border-radius: 12px;
}
.navBar--sub {
    .navBar-action, .navBar-action-color--active{
        padding: 6px 13px;
        font-size: 16px;
        font-weight: 500;
        margin: 0 0;
        border-radius: 12px;
        text-decoration: none;
        display: inline-block;
        font-family: $body-secondary-font-family;
    }
    .navBar-action{
        color: stencilColor("quaternary-text-color");    
        border: 1px solid stencilColor("quaternary-border-color");
        background: stencilColor("quaternary-bg-color");
        &:hover{
            color: stencilColor("quaternary-text-color-hover");
            border-color: stencilColor("quaternary-border-color-hover");
            background: stencilColor("quaternary-bg-color-hover");
        }
    }
    .navBar-action-color--active{
        color: stencilColor("quaternary-text-color-hover");
        border: 1px solid stencilColor("quaternary-border-color-hover");
        background: stencilColor("quaternary-bg-color-hover");
    }
    .navBar-item{
        margin: 0;
        + .navBar-item{
            margin-top: 10px;
            @include breakpoint(500px){
                margin-top: 0;
                margin-left: 15px;
            }
        }
    }
}
.navBar-section.account-navigation {
    text-align: left;
    display: flex;
    flex-wrap: wrap;
    flex-direction: column;
    @include breakpoint(500px){
        flex-wrap: nowrap;
        flex-direction: row;
    }
}
.page--cavio .navBar-section {
    &.account-navigation {
        flex-wrap: wrap;
        flex-direction: row;
        .navBar-item {
            + .navBar-item {
                margin-top: 0;
            }
        }
    }
}
.navBar--sub .navBar-item.is-active{
   @include breakpoint("medium"){
    border-bottom-style: none;
   } 
}
.login-form {
    .form-actions{
        *{
            vertical-align: middle;
        }
    }
}
.heroCarousel{
    margin: 0;
    &.slick-dotted.slick-slider{
        margin: 0;
    }
}
.header{
    border: 1px solid #e6e6e6;
    height: auto;
    .container{
        padding: 0 20px;
        @include breakpoint("medium"){
            max-width: 1956px;
            padding: 0 48px;
        }
    }
}
.footer{
    background-color: stencilColor("footer-backgroundColor");
    .container{
        padding: 0 0;
        @include breakpoint("medium"){
            max-width: 1956px;
            padding: 0 48px;
        }
    }
}
.global-banner-text{
    font-size: 13px;
    line-height: 25px;
    color:stencilColor("header-top-text-icon-color");
    text-align: center;
    margin: 0;
    opacity:0;
    transition: opacity $general-trasitions-speed;
    @include breakpoint("medium"){
        font-size: 17px;
        line-height: 25px;        
    }
    &.slick-slide{
        animation: $opacity-animation;
    }
}
.social-icons-top {
    .navUser-item.navUser-item--social{
        margin: 0;
    }
    .socialLinks{
        line-height: 1;
        @include flex-box;
        align-items: center;
        justify-content: center;        
        .socialLinks-item{
            margin-bottom: 0;
            margin-right: 28px;
            @include breakpoint("medium"){
                margin-right: 15px;
            }
            @include breakpoint("large"){
                margin-right: 28px;
            }        
        }
        .icon {
            height: 19px;
            width: 19px;
            svg{
                transition: $buttons-trasitions;
                fill:stencilColor("header-top-text-icon-color");
            }
            &.icon--linkedin{
                svg{
                    stroke:none;
                }
            }
            &:hover{
                svg{
                    fill:stencilColor("header-top-text-icon-Hover-color");
                }               
            }
        }
    }
}
.top-menu{
    background-image: linear-gradient(90deg, $topmenu-bg-color-one 0%, $topmenu-bg-color-two 100%);
    border-bottom: 1px solid #e6e6e6;
    padding: 7px 0;
    @include breakpoint("medium"){
        padding: 10px 0;
        z-index: 52;
        position: relative;
    }
}
.rotating-banner{
    max-width: 530px;
    padding: 0 15px;
    @include breakpoint("medium"){
        max-width: 100%;
    }
    .slick-arrow{
        position: absolute;
        width: 8px;
        height: 12px;
        top: 50%;
        transform: translateY(-50%);    
        fill:stencilColor("header-top-text-icon-color");
        cursor: pointer;
        &:hover{
            fill:stencilColor("header-top-text-icon-Hover-color");
        }
        &.cavio-arrow-left{
            left: 0;
            @include breakpoint("medium"){
                left: 6px;
            }
        }        
        &.cavio-arrow-right{
            right: 0;
            @include breakpoint("medium"){
                right: 6px;
            }
        }
    }
}
.top-nav-user-section{
    ul{
        list-style: none;
        margin: 0;
        @include flex-box;
        justify-content: flex-end;
        .navUser-section{
            float: none;
            display: inline-flex;
        }
    }
}
.navUser--fire-icon{
    display: inline-flex;
    margin-right: 13px;
    svg{
        width: 15px;
        height: 21px;
        fill:stencilColor("header-top-user-links-color");
    }
}
.top-nav-user-section{
    font-family: $body-secondary-font-family;
    .navUser-action{
        display: inline-flex;
        align-items: center;
        justify-content: center;
        font-size: 14px;
        line-height: 26px;
        color: stencilColor("header-top-user-links-color");
        font-weight: 500;
        text-transform: capitalize;
        &:hover{
            color: stencilColor("header-top-Userlinks-Hover-color"); 
            .navUser--fire-icon{
                svg{
                   fill: stencilColor("header-top-Userlinks-Hover-color"); 
                   stroke: stencilColor("header-top-Userlinks-Hover-color");
                }
            }
        }
    }
    > ul{
        > li{
            display: inline-flex;
            align-items: center;
            justify-content: center;
            .navUser-action{
                padding: 0 18px;
                &.navUser-action--currencySelector{
                    padding-right: 0;
                    &:hover{
                        svg{
                           fill: stencilColor("header-top-Userlinks-Hover-color");
                           stroke: stencilColor("header-top-Userlinks-Hover-color");
                        }
                    }
                }
                &:focus-visible{
                    outline-offset: -3px;
                    border-radius: 4px;
                    outline: 3px solid stencilColor("focus-outline");                      
                }
            }        
            & + li {
                &.help-nav-menu {
                    .navUser-action{
                        padding: 0;
                    }
                    &.has-content {
                        .navUser-action{
                            padding: 0 18px;
                        }
                    }
                }
            }          
            &.has-content {
                &::after{
                    content: "|";
                    display: inline-block;
                    font-size: 16px;
                    color:stencilColor("header-top-user-links-color");
                }
            }
            
            &:last-child {
                &::after{
                    content: none;
                }
            }
        }
    }
}
.header-logo__link{
    padding: 8px 0;
    display: flex;
    align-items: center;
    justify-content: flex-start;
    min-height: 54.39px;
    @include breakpoint("medium"){
        padding: 0 0;
        min-height: 56px;
    }
}
.form-field--increments .icon svg{
    stroke: none;
}
.writeReview-productDetails{
    .product-title{
        text-transform: none;
    }
}
.header-logo-image-container{
    @include breakpoint("medium"){
        min-height: auto;
    }
}
.header-logo-text{
    text-transform: none;
    font-weight: 500;
    font-size: 32px;
    letter-spacing: normal;
    line-height: 1.2;
    margin-left: 0;
    overflow: hidden;
    white-space: nowrap;
    @include breakpoint("medium"){
        font-size: stencilNumber("logo_fontSize");
        line-height: 1.4;
    }
}
.header-logo-image, .header-logo-image-unknown-size{
    max-height: 70px;
    margin-left: 0;
    @include breakpoint("medium"){
        max-height: none;
    }
}
.header-logo--center{
    .header-logo-image, .header-logo-image-unknown-size {
        margin-left: auto;
    }
}
.header-logo--center,.header-logo--left-stacked{
    .header-logo-image-container{
        @include breakpoint("medium"){
            display: flex;
            align-items: center;
            justify-content: center;
        }
    }
}
.header-logo-layout-center{
    .header-bottom-wrapper .navUser, .header-bottom-wrapper .navPages-container{
        @include breakpoint("medium"){
            width: 42%;
        }
    }
}
.header-bottom-wrapper{
    @include flex-box;
    align-items: center;
    opacity: 0;
    .navUser,.navPages-container{
        width: 50%;
        @include breakpoint("medium"){
            width: 43%;
        }
        @include breakpoint("large"){
            width: 45%;
        }        
    }
    .header-logo{
        width: 50%;
        margin: 0;
        height: auto;
        text-align: left;
        @include breakpoint("medium"){
            width: 14%;
        }        
        @include breakpoint("large"){
            width: 10%;
        }
        .header-logo__link{
            width: auto;
            display: flex;
        }
        &.header-logo--center{
            @include breakpoint("medium"){
                width: 16%;
            }  
            .header-logo-text {
                @include breakpoint("medium"){
                    margin-left: auto;
                }
            }
        }
    }
    .navPages-container{
        order: 1;
        z-index: 23;
        @include breakpoint("medium"){
            position: static;
        }
        .navPages{
            text-align: left;
            background-color: stencilColor("navPages-subMenu-backgroundColor");
            @include breakpoint("medium"){
                background-color: stencilColor("header-backgroundColor");
            }
        }
        .socialLinks .icon svg{
            fill: stencilColor("navPages-subMenu-text-color");
        }
    }
    .navUser{
        order: 3;
        position: static;
        transform: none;
        padding-right: 51px;
        padding-left: 10px;
        @include breakpoint("medium"){
            padding-right: 0;
        }
    }
    .header-logo--center{
        order: 2;
        @include breakpoint("medium"){
            text-align: center
        }
    }
}
.navUser{
    .navUser-section{
        @include flex-box;
        align-items: center;
        @include breakpoint("medium"){
            justify-content: flex-end;
        }
        li.navUser-item{
            display: none;
            margin-left: 14px;
            @include breakpoint("medium"){
                display: inline-flex;
                margin-left: 10px;
            }
            @include breakpoint("large"){
                margin-left: 10px;
            }
            &.navUser-item--cart, &.navUser-item--search{
                display: inline-flex;
            }
            &.navUser-item--cart{
                position: relative;
            }
            &.navUser-item--search{
                margin-left: 0;
                @include breakpoint("medium"){
                    margin-right: 10px;
                }
                .dropdown--quickSearch{
                    position: static;
                    padding-top: 0;
                    padding-bottom: 0;
                    &.search-popup-disable{
                        filter: none;
                        margin: 0;
                        .form {
                            .form-input{
                                @include breakpoint("medium"){
                                    width: 124px;
                                }
                                @include breakpoint("large"){
                                    width: 157px;
                                }
                                @include breakpoint("xlarge"){
                                    width: 183px;
                                }      
                                @include breakpoint(1800px){
                                    width: 262px;
                                }                          
                            }
                        }
                        .container{
                            padding: 0;

                        }
                    }
                }
                .quick-search-buttons, .search-label-box{
                    display: none;
                    opacity: 0;
                }
                &.search--open{
                    .dropdown--quickSearch{
                        position: fixed;
                        padding-top: 0;
                        padding-bottom: 0;
                        animation: $opacity-animation;
                    }
                    .quick-search-buttons{
                        display: block;
                        animation: $opacity-animation;

                    }
                    .search-label-box{
                        display: flex;
                        animation: $opacity-animation;
                    }
                }
            }
        }
    }
    .navUser-action{
        color: stencilColor("navPages-color");
        display: inline-flex;
        padding: 0;
        font-weight: 500;
        &.navUser-item--compare{
            display: none;
        }
        svg{
            fill: stencilColor("navPages-color");
        }
    }
    .nav-account-dropdown{
        display: none;
    }
    .navUser-action--quickSearch{
        svg{
            width: 26px;
            height: 25px;
            @include breakpoint("medium"){
                width: 27px;
                height: 25px;                
            }
        }
    }
