/*Product Card start*/
.card{
    margin-bottom: 30px;
}
.card-title,.listItem-title{
    font-size: 14px;
    line-height: 20px;    
    font-weight: 500;
    font-family: $body-secondary-font-family;
    margin-bottom: 2px;
    text-align: left;
    @include breakpoint("medium"){
        font-size: 16px;
        line-height: 26px;
        margin-bottom: 8px;
    }
    > a{
        letter-spacing: normal;
        color: $card-title-color;
        &:hover {
            color: $card-title-color-hover;
        }
    }
}
.listItem-content {
    font-family: $body-secondary-font-family;
    .listItem-brand {
        font-size: 14px;
        color: #818181;
    }
}
.listItem-details{
     > :last-child{
        font-family: $body-secondary-font-family;
         font-size: 14px;
     }
}
.cart-action-buttons,.card-figcaption-button.quickview, .card-figcaption-button.compare-button, .card-figcaption-button.wishList span{
    opacity: 0;
    &:focus-visible{
      outline-offset: -3px;
    }    
}
.card-figcaption-body {
    .card-figcaption-button.wishList {
        background-color: transparent;
        border-color: transparent;
        transition: $buttons-trasitions;
        span{
            display: block;
            margin-right: 6px;
            transition: opacity $general-trasitions-speed;
            @include breakpoint("medium"){
                margin-right: 7px;
            }
        }
        .icon{
            margin-left: 0;
        }
    }
}
.listItem-figure{
    overflow: hidden;
    .listItem-figure__link{
        display: flex;
        background: #f3f3f3;
        margin: 0;
        padding: 3px;     
        border-radius: 12px;   
    }
}
.listItem{
    margin: 0;
}
.listItem-image{
    border-radius: 12px;
}
.coming-soon-image{
    background-color: stencilColor("image-bg-color");
}
.card-image{
    object-fit: cover;
}
.card-figure,.listItem-figure{
    border-radius: 12px;
    background-color: stencilColor("image-bg-color");
    padding: 0;
    .card-image.secondary-image{
        opacity: 0;
        background-color: stencilColor("image-bg-color");
        transition: transform $general-trasitions-speed,opacity $general-trasitions-speed;
    }
    &:hover{
        .cart-action-buttons,.card-figcaption-button.quickview, .card-figcaption-button.compare-button, .card-figcaption-button.compare-button, .card-figcaption-button.wishList span{
            opacity: 1;
        }
        .card-figcaption-button.wishList {
            background-color: stencilColor("card-figcaption-button-background");
            border-color: stencilColor("card-figcaption-button-border-color");
            span{
                display: block;
            }
        }
        .card-image.secondary-image{
            opacity: 1;
            transform: scale(1.1);
        }

    }
    &:focus-within{
        .cart-action-buttons,.card-figcaption-button.quickview, .card-figcaption-button.compare-button, .card-figcaption-button.compare-button, .card-figcaption-button.wishList span{
            opacity: 1;
        }
    }    
}
.card-body .card-text{
    color: $card-title-color;
}
.listItem-figure{
    background-color: transparent;
}
.card-figure .card-figcaption-button.wishList{
    &:hover{
        background-color: stencilColor("card-figcaption-button-background-hover");
        border-color: stencilColor("card-figcaption-button-border-color-hover");       
    }
}
.card-body{
    padding-top: 16px;
    text-align: left;
    font-family: $body-secondary-font-family;
    @include breakpoint("medium"){
        padding-top: 24px;
    }
    .card-brand-text{
        font-size: 14px;
        line-height: 26px;
        color: stencilColor("color-textSecondary");
        font-weight: 500;
        margin-bottom: 3px;
        @include breakpoint("medium"){
            margin-bottom: 6px;
        }
    }
}
.card-swatches {
    margin-bottom: 11px;
    @include breakpoint("medium"){
        margin-bottom: 13px;
    }
    .lable-more-card.mobile{
        display: inline-block;
        @include breakpoint("medium"){
            display: none;
        }
    }
    .lable-more-card.desktop{
        display: none;
        @include breakpoint("medium"){
            display: inline-block;
        }            
    }    
    .lable-more-card{
        font-size: 17px;
        line-height: 26px;
        color: stencilColor("color-textSecondary");
        font-weight: 500;
        text-decoration: none;
        vertical-align: middle;
    }
    .form-option-swatch{
        margin-right: 4px;
        margin-bottom: 0; 
        vertical-align: middle;
        border-radius: 50%;
        padding: 2px;
        @include breakpoint("medium"){
            margin-right: 4px;
        }
        &.hidemobileswatch{
            display: none;
            @include breakpoint("medium"){
                display: inline-block;
            }
        }
        .card_swatch{
            width: 22px;
            height: 22px;     
            display: inline-flex;
            border-radius: 100%;
            position: relative;
            @include breakpoint("medium"){
                width: 26px;
                height: 26px;                   
            }
            svg{
                width: 14px;
                height: 11px;
                position: absolute;
                top: 0;
                bottom: 0;
                left: 0;
                right: 0;
                margin: auto;                
                fill: #fff;
                opacity: 0;
                transition: $buttons-trasitions;
            }
            span{
                width: 100%;
                height: 100%;
                border-radius: 100%;
                &::before{
                    content: "";
                    display: block;
                    position: absolute;
                    height: 100%;
                    background: transparent;
                    border-radius: 100%;
                    top: 0;
                    border: 0;
                    left: 0;
                    right: 0;
                    border: 1px solid transparent;
                    transition: $buttons-trasitions;
                    @include breakpoint("medium"){
                        border: 2px solid transparent;
                    }
                }
            }
            &.swatch-selected{
                svg{
                    opacity: 1;
                }
            }
        }
        &.form-option-multiswatch {
            .multi_options {
                overflow: hidden;
                span {
                    border-radius: 0;
                    width: 100%;
                    height: 100%;
                }
            }
        }
    }
}
.card-img-container{
    &::after{
        padding-bottom: 129.3%;
    }
}
.card-text, .listItem-price{
    color: $card-title-color;
    &.card-price-text{
        @include flex-box;
        font-size: 14px;
        line-height: 26px;
        font-weight: 500;
        margin-bottom: 13px;
        @include breakpoint("medium"){
            font-size: 18px;
        }
        .non-sale-price--withoutTax,.rrp-price--withoutTax{
            color: stencilColor("color-textSecondary");
            font-weight: 400;
            order: 2;
        }
        .price-section{
            margin-right: 10px;
        }
    }
}
.icon--ratingEmpty svg{
    fill: stencilColor("icon-ratingEmpty");
}
.icon--ratingFull svg{
    fill: stencilColor("icon-ratingFull");
}
.card-text{
    .icon--ratingFull svg{
        fill: stencilColor("icon-ratingFull");
    }
    .icon--ratingEmpty svg{
        fill: stencilColor("icon-ratingEmpty");
    }
}

