/* Dropdown-products container styling */
.dropdown-products {
    position: relative;
    display: inline-block;
    max-width: 323px;
    width: 100%;
    @include breakpoint("medium"){
        max-width: 100%;
        width: calc(100% - 330px);        
    }
}

/* Style the dropdown-products button */
.dropdown-products-toggle {
    border: none;
    cursor: pointer;
    text-align: left;
    font-size: 26px;
    line-height: 26px;
    text-decoration: underline;
    color: stencilColor("color-textBase");
    font-weight: 500;
    padding: 0;
    display: flex;
    align-items: center;  
    max-width: 323px;
    width: 100%;   
    @include breakpoint("medium"){
        display: none;
    }
    svg{
        width: 14px;
        height: 23px;
        transform: rotate(90deg);
        margin-top: 4px;
        margin-left: 15px;  
        fill: stencilColor("color-textBase");     
        transition: transform $general-trasitions-speed; 
    }
    &.active-dropdown{
        svg{
            transform: rotate(270deg);
        }
    }
}

/* Style the dropdown-products menu */
.dropdown-products-menu {
    display: none;
    position: absolute;
    border: 1px solid stencilColor("container-border-global-color-base");
    list-style: none;
    padding: 0;
    margin: 0;
    width: 100%;
    z-index: 1000;
    @include breakpoint("medium"){
        display: block !important;
        position: static;
        border: none;
    }
}

/* Style each dropdown-products item */
.dropdown-products-menu .tab {
    padding: 10px;
    cursor: pointer;
    @include breakpoint("medium"){
        padding: 0;
        margin-right: 20px;
    }
    @include breakpoint("large"){
       margin-right: 66px; 
    }
}

.dropdown-products-menu .tab.is-active {
    background-color: stencilColor("container-border-global-color-base");
    @include breakpoint("medium"){
        background-color: transparent;
    }
    .tab-title{
        @include breakpoint("medium"){
            position: relative;
        }
        &::after{
            @include breakpoint("medium"){
                width: 100%;
                opacity: 1;
            }
        }
    }
}
/* Show the dropdown-products when the menu is visible */
.dropdown-products-menu.show {
    display: block;
}
.card{
    .rating--small{
        .icon{
            margin-right: 5px;
            width: auto;
            height: auto;
            svg{
                width: 19px;
                height: 18px;
