    }
}
/* Initially hidden section start*/
.hidden-section {
    display: none;
    opacity: 0;
    transform: translateY(-50px);
    transition: opacity $general-trasitions-speed, transform $general-trasitions-speed;
    filter: drop-shadow(0px 8px 7.5px rgba(0,0,0,0.1));
