            padding: 0;
            @include breakpoint(1366px){
                width: 69%;
            }
            @include breakpoint(1550px){
                width: 63.5%;
            }
            .cart-header {
                .cart-header-item {
                    font-size: 16px;
                    color: stencilColor("color-textBase");
                    font-weight: 500;
                    padding: 0;
                    span {
                        padding: 11px 0;
                        background-color: stencilColor("cart-bg-color");
                        display: block;
                        border: 1px solid stencilColor("container-border-global-color-base");
                        &::after{
                            content: ":";
                        }
                    }
                    &:nth-child(2), &:nth-child(3) {
                        span {
                            border-left: none;
                            border-right: none;
                        }
                    }
                    &:nth-child(3) {
                        span {
                            text-align: left;
                            padding-left: 20px;
                        }
                    }
                    &:nth-child(1) {
                        span {
                            border-radius: 12px 0 0 12px;
                            border-right: none;
                            padding-left: 19px;
                        }
                    }
                    &:nth-last-child(1) {
                        span {
                            border-radius: 0 12px 12px 0;
                            border-left: none;
                            padding-right: 22px;
                        }
                    }
                }
            }
            .cart-list {
                border-top: none;
                position: relative;
                .cart-item-block {
                    padding: 0 0 0;
                    @include breakpoint("medium"){
                        padding: 40px 0 45px;
                        display: table-cell;
                        width: 16%;
                    }
                    &.cart-item-figure {
                        width: 105px;
                        height: 136px;
                        margin: 0;
                        position: absolute;
                        left: 15px;
                        border-radius: 12px;
                        background-color: stencilColor("image-bg-color");
                        display: flex;
                        align-items: center;
                        justify-content: center;                        
                        @include breakpoint("medium"){
                            max-width: 134px;
                            width: 134px;
                            max-height: 174px;
                            padding: 40px 0;
                            left: 0;
                            position: relative;
                            display: table-cell;
                            background-color: transparent;
                        }
                        .cart-figure-wrapper{
                            background-color: stencilColor("image-bg-color");
                            border-radius: 12px;
                            overflow: hidden;
                            @include breakpoint("medium"){
                                width: 134px;
                                height: 174px;
                                position: relative;
                                display: flex;
                                align-items: center;
                                justify-content: center;
                                flex-wrap: wrap;
                                padding: 0;
                            }                           
                            &::after{
                                @include breakpoint("medium"){
                                    content: "";
                                    display: block;
                                    height: 100%;
                                    left: 0;
                                    position: absolute;
                                    top: 0;
                                    width: 100%;  
                                }
                            }                          
                        }
                        img {
                            max-height: 100%;
                            max-width: 100%;
                            width: 100%;
                            height: auto;
                            object-fit: cover;
                        }
                    }
                    &.cart-item-title {
                        height: auto;
                        display: table-cell;
                        @include breakpoint("medium"){
                            width: 322px;
                            padding-left: 31px;
                            padding-right: 31px;
                            display: table-cell;
                        }
                        .cart-item-name {
                            letter-spacing: 0;
                            font-weight: 500;
                            margin-bottom: 12px;
                            font-size: 14px;
                            line-height: 20px;
                            @include breakpoint("medium"){
                                font-size: 18px;
                                line-height: 26px;                                
                            }
                            a {
                                color: stencilColor("color-textBase");
                                text-decoration: none;
                            }
                        }
                        .cart-item-brand {
                            font-size: 12px;
                            line-height: 20px;
                            color: stencilColor("color-textSecondary");
                            font-weight: 400;
                            display: block;
                            margin-bottom: 1px;
                            @include breakpoint("medium"){
                                display: none;                            
                                font-size: 16px;
                                line-height: 30px;
                                margin-bottom: 4px;
                            }
                        }
                        .definitionList-key {
                            font-size: 12px;
                            line-height: 20px;                            
                            color: stencilColor("color-textBase");
                            font-weight: 500;
                            @include breakpoint("medium"){
                                font-size: 16px;
                                line-height: 32px;                                
                            }
                        }
                        .definitionList-value {
                            font-size: 12px;
                            line-height: 20px;  
                            color: stencilColor("color-textBase");
                            font-weight: 400;
                            @include breakpoint("medium"){
                                font-size: 16px;
                                line-height: 32px;                                
                            }                            
                        }
                        .edit-otpion-text {
                            display: none;
                            font-size: 11px;
                            text-decoration: underline;
                            font-weight: 400;
                            color: stencilColor("ft-copy-hover");
                            border-bottom: 1px solid stencilColor("ft-copy-hover");
                            text-transform: capitalize;                            
                            @include breakpoint("medium"){
                                text-decoration: none;
                                display: inline-block;
                                font-size: 16px;
                                line-height: 26px; 
                                border: none;
                                text-decoration: underline;
                                margin-top: 3px;                       
                            }
                        }
                    }
                    &.cart-item-info {
                        .cart-item-value  {
                            font-size: 20px;
                            line-height: 28px;
                            color: stencilColor("color-textBase");
                            font-weight: 500;
                            padding-right: 35px;
                        }
                        &.cart-item-info-totalprice.mobile-view{
                            padding-top: 7px;
                            width: 100%;
                            @include breakpoint("medium"){
                                display: none;
                            }                            
                            .cart-item-label{
                                display: none;
                            }
                            .cart-item-value {
                                font-size: 14px;
                                line-height: 20px;
                                padding: 0;
                            }
                        } 
                        &.cart-item-info-totalprice.desktop-view{
                            display: none;
                            @include breakpoint("medium"){
                                display: table-cell;
                                width: 16%;
                            }
                        }                       
                    }
                    &.cart-item-quantity {
                        width: 160px;
                        padding-top: 8px;
                        @include breakpoint("medium"){
                            display: table-cell;
                            width: 21.3%;
                            padding-top: 40px;
                            padding-bottom: 45px;
                        }
                        @include breakpoint(1366px){
                            width: 25.3%;
                        }
                        @include breakpoint("xlarge"){
                            width: 22.3%;
                        }
                        .cart-qty-main {
                            display: flex;
                            align-items: center;
                            justify-content: flex-start;
                            flex-wrap: wrap;
                            @include breakpoint("medium"){
                                justify-content: center;
                            }
                            .cart-item-label{
                                width: auto;
                                margin: 0;
                                font-size: 11px;
                                color: stencilColor("color-textBase");
                                font-weight: 400;
                                padding: 0 5px;  
                                margin-left: 6px;
                                margin-bottom: -9px;
                                position: relative;
                                background: stencilColor("input-bg-color");                                                         
                            }
                        }
                        .form-increment {
                            border-radius: 12px;
                            background-color: stencilColor("button--default-BG");
                            border: 1px solid stencilColor("button--default-borderColor");
                            height: 48px;
                            margin: 0;
                            display: flex;
                            align-items: center;
                            justify-content: space-between;
                            max-width: 113px;
                            padding: 11px;
                            font-size: 16px;
                            width: 100%;
                            margin-bottom: 18px;
                            @include breakpoint("medium"){
                                margin-bottom: 0;
                            }
                            .form-input--incrementTotal {
                                color: stencilColor("color-textBase");
                                font-weight: 400;
                                font-size: 14px;
                                background-color: transparent;
                                @include breakpoint("medium"){
                                    font-weight: 400;
                                    font-size: 16px;                                    
                                }
                            }
                            .button {
                                border: none;
                                padding: 0;
                                border: none;
                                outline: none;
                                background-color: transparent;
                                .icon {
                                    width: 20px;
                                    height: 20px;
                                    svg {
                                        fill: stencilColor("color-textBase");
                                        stroke: none;
                                    }
                                }
                            }
                        }
                        .cart-remove {
                            width: auto;
                            height: auto;
                            font-size: 16px;
                            line-height: 20px;
                            border-bottom: 1px solid stencilColor("ft-copy-hover");
                            border-radius: 0;
                            color: stencilColor("ft-copy-hover");
                            font-weight: 400;
                            background: none;
                            padding: 0;
                            margin-left: 13px;
                            margin-top: 0;
                            &:focus, &:focus-visible {
                                outline: none !important;
                            }
                        }
                    }
                    .product-changes-buttons{
                        width: 100%;
                        @include breakpoint("medium"){
                            width: auto;
                        }
                        .product-change-button{
                            font-size: 11px;
                            text-decoration: none;
                            border-bottom: 1px solid stencilColor("ft-copy-hover");
                            color: stencilColor("ft-copy-hover");
                            font-weight: 400;
                            display: inline-block;
                            vertical-align: top;  
                            line-height: 14px; 
                            float: none;
                            margin-left: 0;
                            @include breakpoint("medium"){
                                font-size: 16px;
                                display: flex;
                                margin-left: 13px;
                            }
                            + .product-change-button{
                                margin-left: 20px;
                                position: relative;
                                &:before{
                                    content: "|";
                                    display: inline-flex;
                                    color: stencilColor("ft-copy-hover");
                                    position: absolute;
                                    left: -12px;
                                    top: 2px;
                                    pointer-events: none;                                    
                                }
                            }
                            &.edit-otpion-text{
                                @include breakpoint("medium"){
                                    display: none;
                                }
                            }                
                        }
                    }
                    &:nth-last-child(1) {
                        width: 117px;
                        padding-left: 20px;
                    }
                }
            }
        }
        .cart-content-padding-right{
            padding-right: 0;
            @include breakpoint(1366px){
                padding-right: 20px;
            }
            @include breakpoint(1550px){
                padding-right: 39px;
            }
        }
        .right-summary-content {
            width: 100%;
            margin: 0 auto;
            max-width: 100%;
            padding: 0 15px;
            @include breakpoint("medium"){
                max-width: 100%;
                width: 100%;
                padding: 0;
                margin: 0 auto;
            }
            @include breakpoint(1366px){
                width: 31%;
            }
            @include breakpoint(1550px){
                width: 36.5%;
            }
            .cart-content-padding-right{
                @include breakpoint("medium"){
                    padding-right: 0;
                }
            }
            .cart-totals{
               width: 100%;
               @include breakpoint("medium"){
                margin-bottom: 7px;
               }
            }
            .cart-actions {
                .button{
                    display: block;
                    float: none;
                    @include breakpoint("medium"){
                        font-size: 20px;
                        line-height: 26px;
                        padding-top: 16px;
                        padding-bottom: 16px;                        
                    }
                    @include breakpoint(1366px){
                        font-size: 15px;
                        padding-right: 8px;
                        padding-left: 8px;                           
                    }
                    @include breakpoint(1570px){
                        font-size: 20px;
                        padding-right: 18px;
                        padding-left: 18px;          
                    }
                }
            }
        }
        .sub-total-price{
            font-size: 12px;
            color: stencilColor("color-textBase");
            font-weight: 400;
            @include breakpoint("medium"){
                font-size: 20px;
                font-weight: 500;
            }
        }
    }
    .grand-total-cart{
        border-radius: 12px;
        background-color: stencilColor("cart-bg-color");
        border: 1px solid stencilColor("container-border-global-color-base");
        align-items: center;
        padding: 11px 14px 11px 25px;
        margin-top: 22px;
        @include breakpoint("medium"){
            margin-top: 0;
            border-radius: 0;
            background-color: transparent;
            border: none;
            border-top: 3px solid stencilColor("cart-bg-color");
            padding-left: 9px;
            padding-right: 0;
        }
        .cart-total-label, .cart-total-grandTotal{
            font-size: 16px;
            color: stencilColor("color-textBase");
            font-weight: 500;   
            strong{
                font-weight: 500;
            }         
        }
        &.cart-total{
            @include breakpoint("medium"){
                padding-top: 28px;
            }
        }
        .cart-total-grandTotal{
            font-size: 20px;
            font-family: $body-secondary-font-family;
        }
    }
}
.modal-body.quickView{
    .productView{
        transition: opacity $general-trasitions-speed;
        opacity: 1;
    }
}
.desktop-usp-sections{
    display: none;
    @include breakpoint("medium"){
        display: block;
    }
}
.mobile-usp-sections{
    @include breakpoint("medium"){
        display: none;
    }
}
.cart-total{
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 12px;
    flex-wrap: wrap;
    @include breakpoint("medium"){
        padding-left: 9px;
    }
    .shipping-estimator {
        width: 100%;
        padding-top: 12px;
        @include breakpoint("medium"){
            padding-top: 25px;
        }
    }
    .estimator-form .button--primary{
        padding: 8px 10px;
        color: stencilColor("quaternary-text-color");
        background: stencilColor("quaternary-bg-color");
        border: 1px solid stencilColor("quaternary-border-color");
        &:hover {
            border-color: stencilColor("quaternary-border-color-hover");
            background-color: stencilColor("quaternary-bg-color-hover");
            color: stencilColor("quaternary-text-color-hover");
        }
        @include breakpoint("medium"){
            font-size: 18px;
            line-height: 26px;
            width: 72%; 
            padding: 16px 10px;   
            margin-bottom: 0;         
        }
        @include breakpoint(1366px){
            width: 67%;
        }
        @include breakpoint("xlarge"){
            width: 65%; 
        }
        @include breakpoint(1550px){
            width: 72%; 
        }     
