        border-radius: 12px;
        @include breakpoint("medium"){
            margin-bottom: 5px;
        }
    }
    .coupon-form .form-input, .cart-gift-certificate-form .form-input{
        font-size: 12px;
        width: 80%;
        border: none;
        color: stencilColor("color-textSecondary");
        @include breakpoint("medium"){
            font-size: 16px;
            height: 60px;
            padding: 10px 20px;
            width: 72%;
        }
    }
    .coupon-form .button, .cart-gift-certificate-form .button{
        margin: 0;
        height: 32px;
        @include breakpoint("medium"){
            height: 60px;
            font-size: 18px;
            width: 28%;
        }
    }
    .form-input, .form-select{
        height: 32px;
    }
    .button{
        font-size: 12px;
        padding: 8px 10px;
    }
    .cart-total-label, .cart-total-value{
        width: 50%;
    }
    .cart-total-label{
        text-align: left;
        padding: 0 0 0 0;
        font-size: 12px;
        color: stencilColor("color-textBase");
        font-weight: 400;
        strong{
            font-weight: 400;
        }
        @include breakpoint("medium"){
            font-size: 18px;
            color: stencilColor("color-textBase");
            font-weight: 500;            
        }
    }
    .cart-show-hide-button{
        font-size: 12px;
        text-decoration: underline;
        color: stencilColor("ft-copy-hover");
        font-weight: 400;  
        @include breakpoint("medium"){
            font-size: 16px;
        }      
    }
    .cart-total-value{
        text-align: right;
        padding: 0 0 0 0;
        line-height: 16px;
    }
    .form-inlineMessage{
        font-size: 12px;
        line-height: 1.3;
    }
    .cart-form{
        width: 100%;
    }
}
.cart-total + .cart-total{
