.myBar{
    height: 8px;
    border-radius: 4px;
    background: stencilColor("progressbar-bg-color");
    transition: $buttons-trasitions;
    width: 100%;
    display: flex;
    flex-wrap: wrap;
    .myProgresslabel{
        background: linear-gradient(90deg, stencilColor("progress-bg-color") 0%, stencilColor("progress-icon-color") 100%);
        position: relative;        
        min-width: 22px;
        width: 0;
        transition: $buttons-trasitions;
        border-radius: 4px;
    }
    .progress-bar-width{
        position: absolute;
        left: auto;
        right: 0;
        width: 22px;
        height: 22px;
        border-radius: 50%;
        background: stencilColor("progress-icon-color");
        top: 50%;
        transform: translateY(-50%);
        display: flex;
        align-items: center;
        justify-content: center;
        transition: $buttons-trasitions;
        svg{
            width: 13px;
            height: 10px;
            fill: #fff;
        }          
    }
}
