            font-weight: 800;
        }
    }
    .product-panel-title {
        font-weight: 800;
    }
    .button--primary, .confirm.button {
        font-weight: 800;
    }
    .breadcrumb:not(:first-child)::before {
        height: 20px;
    }
    ul.subcategories {
        &.subcategories-buttons {
