}
/* Blog Listing Page Start */
.blog--cavio {
    .body {
        .container {
            padding: 0 6rem;
            max-width: 114.85714rem;
            @media screen and (max-width: 1261px) {
                padding: 0 1rem;        
            }
        }
    }
    .blog-wrapper{
        display: flex;
        align-items: flex-start;
        flex-wrap: wrap;
        @include breakpoint("medium"){
            margin: 0 -10px;
        }
        .blog{
            width: 100%;
            padding: 0;
            border: none;
            @include breakpoint("medium"){
                margin: 0 10px 50px;
                width: calc(50% - 20px);
            }
            @include breakpoint("large"){
                width: calc(33.33% - 20px);
            }
            .blog-post-figure {
                width: 100%;
            }
            .blog-post-body {
                width: 100%;
                .blog-date, .blog-author {
                    margin-bottom: 5px;
                }
                .blog-header {
                    .blog-title {
                        margin-right: 0;
                    }
                }
                .blog-post {
                    .rd-more {
                        display: block;
                        margin-top: 10px;
                        text-transform: capitalize;
                        font-weight: 500;
                    }
                }
            }
        }
    }
}
/* Blog Listing Page End */
